-- pandora-primitive: pandora-crm@1.0.0
-- target: customer-app-runtime-only
DO $$ BEGIN IF to_regclass('public.project_specs') IS NOT NULL OR to_regclass('public.projectos_execution_plans') IS NOT NULL OR to_regclass('public.pandora_projects') IS NOT NULL THEN RAISE EXCEPTION 'pandora-crm customer primitive refused on Pandora Control Plane-like schema'; END IF; END $$;
CREATE TABLE IF NOT EXISTS public.primitive_crm_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,name text,email text,phone text,company text,source text,status text,owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,tags text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,scope_id));
CREATE TABLE IF NOT EXISTS public.primitive_crm_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,contact_id uuid NOT NULL,status text NOT NULL,source text,owner_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(contact_id,scope_id) REFERENCES public.primitive_crm_contacts(id,scope_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.primitive_crm_interactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,contact_id uuid NOT NULL,type text NOT NULL CHECK(type IN('note','call','email','meeting','status_change')),note text CHECK(char_length(note)<=4000),actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(contact_id,scope_id) REFERENCES public.primitive_crm_contacts(id,scope_id) ON DELETE CASCADE);
ALTER TABLE public.primitive_crm_contacts ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_crm_contacts FORCE ROW LEVEL SECURITY;ALTER TABLE public.primitive_crm_leads ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_crm_leads FORCE ROW LEVEL SECURITY;ALTER TABLE public.primitive_crm_interactions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_crm_interactions FORCE ROW LEVEL SECURITY;REVOKE ALL ON public.primitive_crm_contacts,public.primitive_crm_leads,public.primitive_crm_interactions FROM anon,authenticated;GRANT SELECT ON public.primitive_crm_contacts,public.primitive_crm_leads,public.primitive_crm_interactions TO authenticated;
CREATE POLICY primitive_crm_contacts_read ON public.primitive_crm_contacts FOR SELECT TO authenticated USING(public.primitive_has_permission(scope_id,'crm.read'));CREATE POLICY primitive_crm_leads_read ON public.primitive_crm_leads FOR SELECT TO authenticated USING(public.primitive_has_permission(scope_id,'crm.read'));CREATE POLICY primitive_crm_interactions_read ON public.primitive_crm_interactions FOR SELECT TO authenticated USING(public.primitive_has_permission(scope_id,'crm.read'));
